`,(document.head||document.documentElement).appendChild(r)}catch{}})(),(()=>{try{const e="tp-oh58",n=document.getElementById(e);n&&n.remove();const r=document.createElement("style");r.id=e,r.textContent=`/* tp-oh58: expenses / fuel popup \u2014 full width, no sideways scroll, no black holes */
